import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
try:
    import fastcc
    _enc = fastcc.enc
except Exception:  # fallback
    _enc = None
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

_T = int(os.environ.get("CC_T", min(os.cpu_count() or 4, 12)))
_CS = int(os.environ.get("CC_CS", 65536))


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        pt = problem["plaintext"]
        aad = problem.get("associated_data") or b""
        if len(key) != 32 or len(nonce) != 12:
            raise ValueError("bad key/nonce")
        if _enc is None:
            ct = ChaCha20Poly1305(key).encrypt(nonce, pt, aad)
            return {"ciphertext": ct[:-16], "tag": ct[-16:]}
        ct, tag = _enc(key, nonce, pt, aad, _T, _CS)
        return {"ciphertext": ct, "tag": tag}

