typedef unsigned __int128 u128;
typedef uint64_t u64;
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static inline u64 ld64(const unsigned char *p){u64 v; memcpy(&v,p,8); return v;}

static void poly_blocks(u64 h[3], u64 r0, u64 r1, const unsigned char *inp, size_t nblk){
    u64 s1 = r1 + (r1>>2);
    u64 h0=h[0],h1=h[1],h2=h[2],c; u128 d0,d1;
    while(nblk--){
        h0 = (u64)(d0 = (u128)h0 + ld64(inp));
        h1 = (u64)(d1 = (u128)h1 + (d0>>64) + ld64(inp+8));
        h2 += (u64)(d1>>64) + 1;
        d0 = ((u128)h0*r0) + ((u128)h1*s1);
        d1 = ((u128)h0*r1) + ((u128)h1*r0) + (h2*s1);
        h2 = h2*r0;
        h0 = (u64)d0;
        h1 = (u64)(d1 += d0>>64);
        h2 += (u64)(d1>>64);
        c = (h2>>2) + (h2 & ~(u64)3);
        h2 &= 3;
        h0 += c; c = (h0 < c);
        h1 += c; c = (h1 < c);
        h2 += c;
        inp += 16;
    }
    h[0]=h0;h[1]=h1;h[2]=h2;
}

typedef struct {
    const unsigned char *in; unsigned char *out; size_t off, len; int last;
    unsigned int key[8]; unsigned int ctr[4]; u64 r0, r1; u64 h[3];
} job_t;

#define SUB 16384
static void *worker(void *arg){
    job_t *j=(job_t*)arg;
    u64 h[3]={0,0,0};
    size_t pos=0;
    unsigned int ctr[4]; memcpy(ctr,j->ctr,16);
    ctr[0] = j->ctr[0] + (unsigned int)(j->off/64);
    while(pos < j->len){
        size_t n = j->len - pos; if(n>SUB) n=SUB;
        ChaCha20_ctr32(j->out+j->off+pos, j->in+j->off+pos, n, j->key, ctr);
        ctr[0] += (unsigned int)(n/64);
        size_t nb = n/16;
        poly_blocks(h, j->r0, j->r1, j->out+j->off+pos, nb);
        size_t rem = n - nb*16;
        if(rem){
            unsigned char buf[16]={0};
            memcpy(buf, j->out+j->off+pos+nb*16, rem);
            poly_blocks(h, j->r0, j->r1, buf, 1);
        }
        pos += n;
    }
    memcpy(j->h,h,24);
    return NULL;
}

#define MAXT 64
/* enc(key32, nonce12, pt, nthreads) -> (ct_bytes, polykey32, list of (h0,h1,h2,end_block)) */
static PyObject *enc(PyObject *self, PyObject *args){
    Py_buffer kb, nb, pb; int T;
    if(!PyArg_ParseTuple(args,"y*y*y*i",&kb,&nb,&pb,&T)) return NULL;
    size_t len = pb.len;
    PyObject *ct = PyBytes_FromStringAndSize(NULL, len);
    if(!ct){PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);return NULL;}
    unsigned int key[8], ctr[4];
    memcpy(key, kb.buf, 32);
    ctr[0]=0; memcpy(ctr+1, nb.buf, 12);
    unsigned char zero[64]={0}, pk[64];
    ChaCha20_ctr32(pk, zero, 64, key, ctr);
    u64 r0 = ld64(pk) & 0x0ffffffc0fffffffULL;
    u64 r1 = ld64(pk+8) & 0x0ffffffc0ffffffcULL;
    if(T<1)T=1; if(T>MAXT)T=MAXT;
    size_t nblk64 = len/64;
    if((size_t)T > nblk64/64) T = nblk64/64 ? (int)(nblk64/64) : 1;
    job_t jobs[MAXT]; pthread_t th[MAXT];
    size_t per = (nblk64 / T)*64;
    unsigned char *out = (unsigned char*)PyBytes_AS_STRING(ct);
    Py_BEGIN_ALLOW_THREADS
    for(int i=0;i<T;i++){
        jobs[i].in=pb.buf; jobs[i].out=out; jobs[i].off=per*i;
        jobs[i].len = (i==T-1) ? len - per*i : per;
        memcpy(jobs[i].key,key,32); memcpy(jobs[i].ctr,ctr,16); jobs[i].ctr[0]=1;
        jobs[i].r0=r0; jobs[i].r1=r1;
        if(i>0) pthread_create(&th[i],NULL,worker,&jobs[i]);
    }
    worker(&jobs[0]);
    for(int i=1;i<T;i++) pthread_join(th[i],NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst = PyList_New(T);
    for(int i=0;i<T;i++){
        size_t endb = (jobs[i].off + jobs[i].len + 15)/16;
        PyList_SET_ITEM(lst,i,Py_BuildValue("(KKKn)",(unsigned long long)jobs[i].h[0],(unsigned long long)jobs[i].h[1],(unsigned long long)jobs[i].h[2],(Py_ssize_t)endb));
    }
    PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);
    return Py_BuildValue("(NNy#)", ct, lst, (const char*)pk, (Py_ssize_t)32);
}
static PyMethodDef M[]={{"enc",enc,METH_VARARGS,""},{NULL,NULL,0,NULL}};
static struct PyModuleDef md={PyModuleDef_HEAD_INIT,"fastcc",NULL,-1,M};
PyMODINIT_FUNC PyInit_fastcc(void){return PyModule_Create(&md);}
