import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fastcc

P = (1 << 130) - 5
_T = int(os.environ.get("CC_T", min(os.cpu_count() or 4, 12)))
_CS = int(os.environ.get("CC_CS", 262144))


def _poly_bytes(h, r, data):
    n = len(data)
    for i in range(0, n, 16):
        blk = data[i:i + 16]
        if len(blk) < 16:
            blk = blk + b"\0" * (16 - len(blk))
        h = ((h + int.from_bytes(blk, "little") + (1 << 128)) * r) % P
    return h


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        pt = problem["plaintext"]
        aad = problem.get("associated_data") or b""
        if len(key) != 32 or len(nonce) != 12:
            raise ValueError("bad key/nonce")
        ct, parts, pk, cs = fastcc.enc(key, nonce, pt, _T, _CS)
        r = int.from_bytes(pk[:16], "little") & 0x0ffffffc0ffffffc0ffffffc0fffffff
        s = int.from_bytes(pk[16:32], "little")
        h = _poly_bytes(0, r, aad)
        rk = pow(r, cs // 16, P)
        n = len(pt)
        last = len(parts) - 1
        for i, (h0, h1, h2) in enumerate(parts):
            hi = h0 | (h1 << 64) | (h2 << 128)
            if i == last:
                nb = (n - i * cs + 15) // 16
                h = (h * pow(r, nb, P) + hi) % P
            else:
                h = (h * rk + hi) % P
        lens = len(aad).to_bytes(8, "little") + n.to_bytes(8, "little")
        h = _poly_bytes(h, r, lens)
        tag = ((h + s) & ((1 << 128) - 1)).to_bytes(16, "little")
        return {"ciphertext": ct, "tag": tag}
