    bl[4]=_mm256_unpacklo_epi64(a4,a6); bl[5]=_mm256_unpackhi_epi64(a4,a6);
    bl[6]=_mm256_unpacklo_epi64(a5,a7); bl[7]=_mm256_unpackhi_epi64(a5,a7);
    for(int j=0;j<4;j++){
      __m256i lo=_mm256_permute2x128_si256(bl[j],bl[j+4],0x20);
      __m256i hi=_mm256_permute2x128_si256(bl[j],bl[j+4],0x31);
