/* process len bytes (multiple of 512 not required): out=in^ks, poly over out (zero-padded last block). counter starts ctr. */
static void stitched(unsigned char *out, const unsigned char *in, size_t len, const uint32_t st[16], uint32_t ctr, uint64_t *H, uint64_t r0, uint64_t r1){
  size_t ng = len/512;
  const unsigned char *pp = NULL;
  for(size_t g=0; g<ng; g++){
    chacha8_poly(out+g*512, in+g*512, st, ctr, pp, H, r0, r1);
    pp = out+g*512; ctr += 8;
  }
  uint64_t h0=H[0],h1=H[1],h2=H[2], s1=r1+(r1>>2);
  if(pp){ for(int k=0;k<32;k++) PSTEP(pp+16*k); }
  size_t done = ng*512, rem = len-done;
  if(rem){
    unsigned char ib[512]={0}, ob[512];
    memcpy(ib, in+done, rem);
    H[0]=h0;H[1]=h1;H[2]=h2;
    chacha8_poly(ob, ib, st, ctr, NULL, H, r0, r1);
    memcpy(out+done, ob, rem);
    memset(ob+rem, 0, 512-rem);
    size_t nb=(rem+15)/16;
    for(size_t k=0;k<nb;k++) PSTEP(ob+16*k);
  }
  H[0]=h0;H[1]=h1;H[2]=h2;
}
